select p.id, snap.id, 'GENERALIZED_FROM_OFFICIAL_SOURCE', 'VALIDATED', geom.g, extensions.ST_PointOnSurface(geom.g),
       array[extensions.ST_XMin(extensions.Box3D(geom.g)), extensions.ST_YMin(extensions.Box3D(geom.g)), extensions.ST_XMax(extensions.Box3D(geom.g)), extensions.ST_YMax(extensions.Box3D(geom.g))]::double precision[],
       '{"source":"ISTAT regione Puglia"}'::jsonb, '{"engine":"istat-admin-region","simplify":"mapshaper 6%","holes":"dropped","coordinate_precision":5}'::jsonb,
       '20260907T000000Z', true, now()
from wine_places p, snap, geom where p.canonical_key = 'italy.puglia';

do $$
declare n int; bx double precision[];
begin
  select count(*) into n from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.puglia' and b.is_current and b.quality_status='VALIDATED';
  if n <> 1 then raise exception 'expected 1 current Puglia region boundary, got %', n; end if;
  select b.bbox into bx from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.puglia' and b.is_current;
  if bx[1] < 14.9 or bx[2] < 39.7 or bx[3] > 18.6 or bx[4] > 42 then raise exception 'Puglia region bbox escapes window: %', bx; end if;
end $$;

