declare n int; bx double precision[];
begin
  select count(*) into n from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.abruzzo' and b.is_current and b.quality_status='VALIDATED';
  if n <> 1 then raise exception 'expected 1 current Abruzzo region boundary, got %', n; end if;
  select b.bbox into bx from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.abruzzo' and b.is_current;
  if bx[1] < 13 or bx[2] < 41.6 or bx[3] > 14.8 or bx[4] > 43 then raise exception 'Abruzzo region bbox escapes window: %', bx; end if;
end $$;

commit;
